WITH with_windows AS (SELECT id, category, brand, cost, stock_qty, launch_date, tags, supplier_id, FIRST_VALUE(cost, TRUE) OVER (ORDER BY cost, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_cost, SUM(price) OVER (PARTITION BY brand ORDER BY launch_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_price, CORR(cost, price) OVER (PARTITION BY supplier_id) AS corr_cost_price FROM products) SELECT DATE_TRUNC('QUARTER', launch_date) AS quarter_start, SORT_ARRAY(COLLECT_SET(brand)) AS brand_list, SIZE(COLLECT_SET(category)) AS num_categories, SIZE(COLLECT_SET(category)) AS num_categories_2, COUNT(*) FILTER (WHERE category = 'Books') AS books_rows, SIZE(COLLECT_SET(brand)) AS num_brands, SORT_ARRAY(COLLECT_SET(brand)) AS brand_list_2 FROM with_windows GROUP BY DATE_TRUNC('QUARTER', launch_date) ORDER BY quarter_start DESC NULLS FIRST;
